import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a cubic bowl, sinusoidal modulation, and pairwise interactions to achieve target ELA features.

    f(x) = sum(x_i^3) + 0.5 * sum(sin(2*x_i)) + 0.1 * sum(x_i * x_j for all i < j) + 0.05 * sum(x_i^2 * cos(x_j) for all i != j)
    """
    n = len(x)
    result = 0.0

    # Cubic bowl
    result += np.sum(x**3)

    # Sinusoidal modulation
    result += 0.5 * np.sum(np.sin(2 * x))

    # Pairwise interactions
    for i in range(n):
        for j in range(i + 1, n):
            result += 0.1 * x[i] * x[j]

    # Interactions with quadratic and cosine terms
    for i in range(n):
        for j in range(n):
            if i != j:
                result += 0.05 * x[i]**2 * np.cos(x[j])


    return float(result)
